\title{A Pfaffian Giambelli Formula for Shifted $t$-Schur Functions: The Algebraic Core}
\author{Aristotle}
\date{June 27, 2026}

\begin{document}

\begin{abstract}
The Schur $Q$-functions indexed by strict partitions admit a classical \emph{Giambelli
formula} expressing each $s_\lambda^Q$ as the Pfaffian of a matrix of two-row Schur
$Q$-functions. Its $t$-deformation---the \emph{shifted $t$-Schur functions} arising from the
odd Greaves--Jing--Zhu (GJZ) operators---preserves this Pfaffian shape exactly, so the
algebraic engine driving both the classical and the deformed formula is the Pfaffian itself.
We isolate and rigorously establish the structural backbone of that engine for the two
smallest nontrivial block sizes: the $2\times 2$ case ($k=1$) and the $4\times 4$ case
($k=2$, the first genuinely interesting Pfaffian). Our main results are: an explicit
first-row Laplace expansion of the $4\times 4$ determinant over an arbitrary commutative ring;
the Pfaffian--determinant identities $\det A = \Pf(A)^2$ for alternating $2\times 2$ and
$4\times 4$ matrices; the alternating sign law (a transposition of indices negates the
Pfaffian, the matrix shadow of Clifford anticommutation); and the complementary-minor
(Giambelli) expansion of the $4\times 4$ Pfaffian as an alternating sum of products of
$2\times 2$ Pfaffians. All results hold over an arbitrary commutative ring.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Motivation}
Schur $Q$-functions are the symmetric functions attached to strict partitions. They control
the projective (spin) representation theory of the symmetric and alternating groups, the
cohomology of isotropic Grassmannians, and the combinatorics of shifted Young tableaux. A
cornerstone is the \emph{Giambelli formula}, reducing an arbitrary Schur $Q$-function to a
Pfaffian of two-row ones. A one-parameter deformation---the \emph{shifted $t$-Schur functions}
$s_\lambda^Q(t)$---arises from odd vertex (GJZ) operators and deforms the Giambelli formula
without changing its shape:
\[
s_\lambda^Q(t) = \Pf\big[\, Y_{\lambda_i - i + j}(t) + Y_{\lambda_j - j + i}(t)\,\big]_{1\le i<j\le k}\cdot \vac,
\]
recovering the classical case at $t=0$. The Clifford anticommutation of the GJZ operators is
precisely what makes a Pfaffian the correct object. We lay down, with full rigor over an
arbitrary commutative ring, the Pfaffian facts these formulas rest upon, at the two smallest
block sizes.

\subsection{Contributions}
Over an arbitrary commutative ring $R$ we establish: (i) \texttt{det\_fin\_four}; (ii)
\texttt{pf2\_sq\_eq\_det}, \texttt{pf4\_sq\_eq\_det}; (iii) \texttt{pf4\_swap12\_neg}; (iv)
\texttt{pf4\_giambelli}. These are the verified base cases ($k=1,2$) of the recursive Pfaffian
Giambelli formula.

\section{Definitions}
Throughout $R$ is a commutative ring, matrices are indexed by $\{0,\dots,n-1\}$, and $A_{ij}$
denotes the $(i,j)$ entry.

\begin{definition}[Alternating matrix]
$A$ is \emph{skew-symmetric} if $A_{ij}=-A_{ji}$ for all $i,j$, and \emph{alternating} if also
$A_{ii}=0$ for all $i$. Over a ring where $2$ is not a zero divisor the two coincide; in general
``alternating'' is strictly stronger.
\end{definition}

\begin{definition}[$2\times 2$ Pfaffian, $k=1$]
For $A\in\Mat_{2\times 2}(R)$, $\Pf_2(A):=A_{01}$.
\end{definition}

\begin{definition}[$4\times 4$ Pfaffian, $k=2$]
For $A\in\Mat_{4\times 4}(R)$,
\[
\Pf_4(A) := A_{01}A_{23} - A_{02}A_{13} + A_{03}A_{12},
\]
a signed sum over the three perfect matchings $\{01,23\},\{02,13\},\{03,12\}$ with signs $+,-,+$.
\end{definition}

\begin{definition}[Submatrix]
For an injection $\iota$, $(A[\iota,\iota])_{ab}=A_{\iota(a)\,\iota(b)}$. We write $A_{ij}$ for
the $2\times 2$ principal submatrix on rows/columns $\{i,j\}$.
\end{definition}

\begin{definition}[Strict partition]
A \emph{strict partition} is $\lambda=(\lambda_1>\dots>\lambda_k\ge 0)$. We write $q(n)$ for the
number of strict partitions of $n$ and $p(n)=|\mathrm{ConjClasses}(S_n)|$ for all partitions.
\end{definition}

\section{Main Results}

\subsection{The $4\times 4$ determinant}
\begin{theorem}[\texttt{det\_fin\_four}]
For every $A\in\Mat_{4\times 4}(R)$,
\begin{align*}
\det A =\;& A_{00}\big(A_{11}(A_{22}A_{33}-A_{23}A_{32}) - A_{12}(A_{21}A_{33}-A_{23}A_{31}) + A_{13}(A_{21}A_{32}-A_{22}A_{31})\big)\\
-\;& A_{01}\big(A_{10}(A_{22}A_{33}-A_{23}A_{32}) - A_{12}(A_{20}A_{33}-A_{23}A_{30}) + A_{13}(A_{20}A_{32}-A_{22}A_{30})\big)\\
+\;& A_{02}\big(A_{10}(A_{21}A_{33}-A_{23}A_{31}) - A_{11}(A_{20}A_{33}-A_{23}A_{30}) + A_{13}(A_{20}A_{31}-A_{21}A_{30})\big)\\
-\;& A_{03}\big(A_{10}(A_{21}A_{32}-A_{22}A_{31}) - A_{11}(A_{20}A_{32}-A_{22}A_{30}) + A_{12}(A_{20}A_{31}-A_{21}A_{30})\big).
\end{align*}
\end{theorem}
\begin{proof}[Proof sketch]
Laplace expansion along row $0$ reduces to four $3\times 3$ minors; apply the $3\times 3$ formula
and evaluate the index shifts explicitly, then normalize by ring arithmetic.
\end{proof}

\subsection{The Pfaffian--determinant identity}
\begin{theorem}[\texttt{pf2\_sq\_eq\_det}, $k=1$]
If $A\in\Mat_{2\times 2}(R)$ is alternating, then $\det A = \Pf_2(A)^2$.
\end{theorem}
\begin{proof}[Proof sketch]
$\det A = A_{00}A_{11}-A_{01}A_{10}$; substitute $A_{00}=A_{11}=0$, $A_{10}=-A_{01}$ to get $A_{01}^2$.
\end{proof}

\begin{theorem}[\texttt{pf4\_sq\_eq\_det}, $k=2$]
If $A\in\Mat_{4\times 4}(R)$ is alternating, then
\[
\det A = \Pf_4(A)^2 = (A_{01}A_{23}-A_{02}A_{13}+A_{03}A_{12})^2.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Start from the $4\times 4$ expansion; impose $A_{ii}=0$ and the six skew relations
$A_{10}=-A_{01},\dots,A_{32}=-A_{23}$. The determinant collapses to the square of the three-term
Pfaffian, a degree-four polynomial identity in twelve entries. This pins down $\Pf$ as the
canonical polynomial square root of $\det$.
\end{proof}

\begin{remark}
$\det A=\Pf(A)^2$ determines $\Pf$ only up to sign; the matching-sum definition fixes the sign
and normalizes $\Pf=+1$ on the standard alternating block.
\end{remark}

\subsection{The alternating sign law}
\begin{theorem}[\texttt{pf4\_swap12\_neg}]
Let $A\in\Mat_{4\times 4}(R)$ be skew-symmetric (zero diagonal not needed), and $\tau=(1\,2)$.
With $A^\tau:=A[\tau,\tau]$,
\[
\Pf_4(A^\tau) = -\Pf_4(A).
\]
\end{theorem}
\begin{proof}[Proof sketch]
$\tau$ fixes $0,3$ and swaps $1\leftrightarrow 2$, giving
$\Pf_4(A^\tau)=A_{02}A_{13}-A_{01}A_{23}+A_{03}A_{21}$; use $A_{21}=-A_{12}$ and reorder to get
$-\Pf_4(A)$.
\end{proof}

\begin{remark}
This is the matrix avatar of Clifford anticommutation $\psi_i\psi_j=-\psi_j\psi_i$. It needs only
skew-symmetry---one hypothesis weaker than the alternating condition for $\Pf^2=\det$.
\end{remark}

\subsection{The complementary-minor Giambelli expansion}
\begin{theorem}[\texttt{pf4\_giambelli}, $k=2$]
For every $A\in\Mat_{4\times 4}(R)$,
\[
\Pf_4(A) = \Pf_2(A_{01})\Pf_2(A_{23}) - \Pf_2(A_{02})\Pf_2(A_{13}) + \Pf_2(A_{03})\Pf_2(A_{12}),
\]
where $A_{ij}=A[\{i,j\},\{i,j\}]$, so $\Pf_2(A_{ij})=A_{ij}$.
\end{theorem}
\begin{proof}[Proof sketch]
$\Pf_2(A_{ij})=A_{ij}$ by definition; substitution reproduces $A_{01}A_{23}-A_{02}A_{13}+A_{03}A_{12}=\Pf_4(A)$.
\end{proof}

\begin{remark}
The general first-row recursion is
$\Pf_{2k}(A)=\sum_{j=2}^{2k}(-1)^j A_{1j}\,\Pf_{2k-2}(A_{\hat 1\hat j})$, of which the $k=2$ case is
the theorem above.
\end{remark}

\section{From the Pfaffian core to shifted $t$-Schur functions}
For a strict partition $\lambda$ (padded to even length $2k$), the classical Giambelli formula is
$s_\lambda^Q=\Pf[s_{(\lambda_i,\lambda_j)}^Q]_{i<j}$ with two-row entries
$s_{(a,b)}^Q=q_aq_b+2\sum_{r=1}^b(-1)^r q_{a+r}q_{b-r}$. The entry matrix is alternating, so the
Pfaffian--determinant identities certify well-definedness and $\Pf^2=\det$.

The $t$-deformation replaces $q_m$ by GJZ modes $Y_m(t)$; the Giambelli Pfaffian persists.
Writing the entry pencil as $A+tB$:
\begin{proposition}[degree bound, $k=2$]
For $A,B\in\Mat_{4\times 4}(R)$,
\[
\Pf_4(A+tB)=\Pf_4(A)+t\,M(A,B)+t^2\,\Pf_4(B),
\]
with $M(A,B)=(A_{01}B_{23}+B_{01}A_{23})-(A_{02}B_{13}+B_{02}A_{13})+(A_{03}B_{12}+B_{03}A_{12})$.
The constant term is $s_\lambda^Q(0)$ and the leading term is $\Pf_4(B)$.
\end{proposition}
Since $\Pf_{2k}$ is homogeneous of degree $k$, $\Pf_{2k}(A+tB)$ is a degree-$\le k$ polynomial in
$t$ with constant term $\Pf_{2k}(A)$ and leading term $t^k\Pf_{2k}(B)$.

\section{Algorithms}
\textbf{Algorithm A (signed-matching Pfaffian).} Enumerate the $(2k-1)!!$ perfect matchings by
fixing the smallest free index and pairing it with each remaining index; accumulate
entry-products times matching signatures. Complexity $O((2k-1)!!\cdot k)$.\\
\textbf{Algorithm B (recursive Giambelli).} First-row cofactor recursion deleting two indices per
step.\\
\textbf{Algorithm C (deformation).} Expand the matching sum on $A+tB$ symbolically in $t$.

\section{Applications}
Projective representation theory of $S_n$ and $A_n$; Schubert calculus on isotropic
Grassmannians; dimer-model and planar-Ising partition functions ($\det=\Pf^2$); Wick's theorem
for free fermions (correlation functions as Pfaffians).

\section{Future Directions}
\begin{conjecture}
For every $k$, $\det A=\pf_{2k}(A)^2$ for alternating $2k\times 2k$ matrices over a commutative
ring, with the recursive first-row expansion.
\end{conjecture}
\begin{conjecture}
$s_\lambda^Q(t)=\Pf(A+tB)$ is polynomial in $t$ of degree $\le k$, constant term $s_\lambda^Q(0)$,
leading term $t^k\Pf(B)$.
\end{conjecture}
\begin{conjecture}
For $n\ge 3$, $q(n)<p(n)=|\mathrm{ConjClasses}(S_n)|$.
\end{conjecture}
\begin{conjecture}
$\sigma\mapsto\pf_{2k}(A[\sigma,\sigma])$ equals $\sign(\sigma)\,\pf_{2k}(A)$ for all $\sigma$.
\end{conjecture}

\section{Conclusion}
We rigorously established the algebraic backbone of the Pfaffian Giambelli formula at $k=1,2$
over an arbitrary commutative ring: the explicit $4\times 4$ determinant, the Pfaffian--determinant
identities, the anticommutation sign law, and the recursive complementary-minor expansion. These
are the load-bearing facts for the general identity and the shifted $t$-Schur deformation.

\end{document}

