function PFAFFIAN(A):
  n <- dim(A); assert n even
  return REC([0,1,...,n-1])

function REC(rem):
  if rem empty: return 1
  i <- rem[0]
  total <- 0
  for pos in 1..len(rem)-1:
    j <- rem[pos]
    sign <- (-1)^(pos-1)
    sub <- rem without positions 0 and pos
    total <- total + sign * A[i][j] * REC(sub)
  return total
